  3	namespace Modules\AI\Infrastructure\Battle;
  4	
  5	use Modules\AI\Domain\Raid\RaidEstimate;
  6	use Modules\AI\Support\SpaceDockRepair;
  7	use OGame\Factories\PlanetServiceFactory;
  8	use OGame\Factories\PlayerServiceFactory;
  9	use OGame\GameMissions\BattleEngine\BattleEngine;
 10	use OGame\GameMissions\BattleEngine\Models\AttackerFleet;
 11	use OGame\GameMissions\BattleEngine\Models\DefenderFleet;
 12	use OGame\GameMissions\BattleEngine\PhpBattleEngine;
 13	use OGame\GameMissions\BattleEngine\RustBattleEngine;
 14	use OGame\GameObjects\Models\Units\UnitCollection;
 15	use OGame\Models\Resources;
 16	use OGame\Services\SettingsService;
 17	
 18	/**
 19	 * The native raid estimator: samples the host's own battle engine as a read-only
 20	 * question.
 21	 *
 22	 * It is not a second battle implementation. Every run asks
 23	 * `simulateBattle($seed, true)` — the pure, seeded shape R1 added — on the engine
 24	 * the host itself fights with (`SettingsService::battleEngine()`), so the engine
 25	 * stays the authority on the rules and a "what if" never touches the world. Both
 26	 * engines are seeded: the Rust FFI carries the seed in its input and derives one
 27	 * stream per side per round, so a screen replays identically whichever engine the
 28	 * universe runs. Rust is roughly 7x faster per simulation, which is why the
 29	 * module no longer pins the PHP engine.
 30	 *
 31	 * The fleet is the account's own ships on the origin planet, and the defender is
 32	 * the host's stationary picture of the target planet, so no unit, price or
 33	 * defence figure is named here.
 34	 */
 35	class NativeRaidEstimator
 36	{
 37	    private const SCREEN_SAMPLES = 50;
 38	
 39	    private const CRYSTAL_WEIGHT = 1.5;
 40	
 41	    private const DEUTERIUM_WEIGHT = 2.0;
 42	
 43	    public function __construct(
 44	        private PlayerServiceFactory $playerServiceFactory,
 45	        private PlanetServiceFactory $planetServiceFactory,
 46	        private SettingsService $settings,
 47	    ) {
 48	    }
 49	
 50	    public function estimate(int $playerId, int $originPlanetId, int $targetPlanetId, int $seed): RaidEstimate
 51	    {
 52	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, null, $seed, self::SCREEN_SAMPLES);
 53	    }
 54	
 55	    /**
 56	     * One simulation of a specific fleet against the target — the launch-subset screen (U6). The
 57	     * fleet is what the caller counter-selected; the engine and the defender stay the host's. The
 58	     * sample count is the caller's ladder rung: one draw for a candidate screen, the wide pass for
 59	     * the winner's confirmation.
 60	     */
 61	    public function estimateFleet(int $playerId, int $originPlanetId, int $targetPlanetId, UnitCollection $fleet, int $seed, int $samples = 1): RaidEstimate
 62	    {
 63	        return $this->screen($playerId, $originPlanetId, $targetPlanetId, $fleet, $seed, $samples);
 64	    }
 65	
 66	    private function screen(int $playerId, int $originPlanetId, int $targetPlanetId, ?UnitCollection $fleet, int $seed, int $samples): RaidEstimate
 67	    {
 68	        $player = $this->playerServiceFactory->make($playerId, true);
 69	        $origin = $this->planetServiceFactory->makeForPlayer($player, $originPlanetId, false);
 70	        $target = $this->planetServiceFactory->make($targetPlanetId, true);
 71	
 72	        if ($target === null) {
 73	            return app()->makeWith(RaidEstimate::class, [
 74	                'samples' => 0,
 75	                'p20NetProfit' => 0.0,
 76	                'p20Loot' => 0.0,
 77	                'pWin' => 0.0,
 78	            ]);
 79	        }
 80	
 81	        $ships = $fleet ?? $origin->getShipUnits();
 82	        if ($ships->units === []) {
 83	            return app()->makeWith(RaidEstimate::class, [
 84	                'samples' => 0,
 85	                'p20NetProfit' => 0.0,
 86	                'p20Loot' => 0.0,
 87	                'pWin' => 0.0,
 88	            ]);
 89	        }
 90	
 91	        $attacker = new AttackerFleet();
 92	        $attacker->units = $ships;
 93	        $attacker->player = $player;
 94	        $attacker->fleetMissionId = 0;
 95	        $attacker->ownerId = $playerId;
 96	        $attacker->cargoResources = new Resources();
 97	        $attacker->isInitiator = true;
 98	        $attacker->fleetMission = null;
 99	
100	        $defender = DefenderFleet::fromPlanet($target);
101	
102	        // The engine the host fights with, not one the module prefers: an
103	        // operator who pins `php` gets the same simulator their battles use.
104	        $engine = match ($this->settings->battleEngine()) {
105	            'php' => new PhpBattleEngine([$attacker], $target, [$defender], $this->settings),
106	            default => new RustBattleEngine([$attacker], $target, [$defender], $this->settings),
107	        };
108	
109	        // The screen is the one bounded pass the decision path may afford; the
110	        // confirmation is a wider sample on the winner only.
111	        $sampled = $this->sample($engine, $seed, $samples);
112	
113	        return app()->makeWith(RaidEstimate::class, [
114	            'samples' => count($sampled['netProfits']),
115	            'p20NetProfit' => $this->lowerQuantile($sampled['netProfits'], 0.2),
116	            'p20Loot' => $this->lowerQuantile($sampled['loots'], 0.2),
117	            'pWin' => $sampled['survived'] / max(1, count($sampled['netProfits'])),
118	        ]);
119	    }
120	
121	    /**
122	     * One bounded screen: the same seed + i stream yields the P20 net (survival),
123	     * the P20 loot (worth-flying) and the survived-run count (fleet survival)
124	     * from identical draws — never a second pass.
125	     *
126	     * @return array{netProfits: list<float>, loots: list<float>, survived: int}
127	     */
128	    private function sample(BattleEngine $engine, int $seed, int $samples): array
129	    {
130	        $netProfits = [];
131	        $loots = [];
132	        $survived = 0;
133	
134	        for ($i = 0; $i < $samples; $i++) {
135	            // One shared stream: seed + i, so a candidate is always compared
136	            // through the same sequence of draws.
137	            $result = $engine->simulateBattle($seed + $i, true);
138	
139	            $loots[] = $this->metalEquivalent($result->loot);
140	            $netProfits[] = $loots[$i] - $this->metalEquivalent($result->attackerResourceLoss);
141	
142	            // getAmount(), not ->units === []: the round sanitizer keeps
143	            // zero-amount entries, so a wiped fleet reads as an empty amount.
144	            $survived += $result->attackerUnitsResult->getAmount() > 0 ? 1 : 0;
145	        }
146	
147	        return ['netProfits' => $netProfits, 'loots' => $loots, 'survived' => $survived];
148	    }
149	
150	    /**
151	     * @param list<float> $values
152	     */
153	    private function lowerQuantile(array $values, float $quantile): float
154	    {
155	        sort($values);
156	        $rank = (int) ceil($quantile * count($values)) - 1;
157	
158	        return $values[max(0, min($rank, count($values) - 1))];
159	    }
160	
161	    public function metalEquivalent(Resources $resources): float
162	    {
163	        return $resources->metal->get()
164	            + self::CRYSTAL_WEIGHT * $resources->crystal->get()
165	            + self::DEUTERIUM_WEIGHT * $resources->deuterium->get();
166	    }
167	}

