  4	
  5	/**
  6	 * The source documents one number for space dock repair: 10% of the total fleet.
  7	 * Combat and raid planning both need that share, so it lives here once instead of
  8	 * being re-derived (and silently re-invented) at each call site.
  9	 *
 10	 * The figure itself lives in resources/behavior/space-dock-repair.yaml so a host
 11	 * that repairs a different share retunes it without editing PHP.
 12	 *
 13	 * The caller is Modules\AI\Infrastructure\Battle\NativeRaidEstimator: it charges a raid only for
 14	 * the share of its loss the dock never brings back.
 15	 */
 16	final class SpaceDockRepair
 17	{
 18	    /**
 19	     * The documented repair share, still public because callers name it directly; the
 20	     * behaviour file below is the retune point and this is only the fallback when a
 21	     * host ships the class without the data.
 22	     */
 23	    public const REPAIR_PERCENT = 10;
 24	
 25	    /** Flat `key: value` data, so a host that repairs a different share retunes it here. */
 26	    private const POLICY_FILE = '/resources/behavior/space-dock-repair.yaml';
 27	
 28	    private const PERCENT_SCALE = 100;
 29	
 30	    private static ?int $repairPercent = null;
 31	
 32	    private function __construct()
 33	    {
 34	    }
 35	
 36	    private static function policyPath(): string
 37	    {
 38	        return dirname(__DIR__, 2) . self::POLICY_FILE;
 39	    }
 40	
 41	    /**
 42	     * Flat `key: value` behaviour data, read without pulling in a YAML parser, the
 43	     * same shape resources/behavior/def-ipm.yaml uses.
 44	     *
 45	     * @return array<string, int|string>
 46	     */
 47	    private static function parse(string $contents): array
 48	    {
 49	        $entries = [];
 50	
 51	        foreach (preg_split('/\R/', $contents) as $line) {
 52	            $line = trim($line);
 53	
 54	            if ($line === '' || str_starts_with($line, '#')) {
 55	                continue;
 56	            }
 57	
 58	            if (! str_contains($line, ':')) {
 59	                continue;
 60	            }
 61	
 62	            [$key, $value] = array_map('trim', explode(':', $line, 2));
 63	
 64	            $entries[$key] = is_numeric($value) ? (int) $value : $value;
 65	        }
 66	
 67	        return $entries;
 68	    }
 69	
 70	    /**
 71	     * Documented repair share of the total fleet, in percent, read by name from the
 72	     * behaviour file so the figure is a modder's number rather than a class constant.
 73	     * The file is read once per process: a retune needs a restart, not a hot reload.
 74	     */
 75	    public static function repairPercent(): int
 76	    {
 77	        if (self::$repairPercent !== null) {
 78	            return self::$repairPercent;
 79	        }
 80	
 81	        $path = self::policyPath();
 82	        $entries = is_file($path) ? self::parse((string) file_get_contents($path)) : [];
 83	
 84	        return self::$repairPercent = (int) ($entries['repair_percent'] ?? self::REPAIR_PERCENT);
 85	    }
 86	
 87	    /**
 88	     * Whole fleet units the space dock restores.
 89	     *
 90	     * Ships are whole units and the source states no rounding rule for fleets that are
 91	     * not a multiple of ten, so the share truncates: fewer than ten units repairs nothing.
 92	     */
 93	    public static function repairedUnits(int $fleetUnits): int
 94	    {
 95	        return intdiv($fleetUnits * self::repairPercent(), self::PERCENT_SCALE);
 96	    }
 97	
 98	    /**
 99	     * Whole fleet units that stay lost once the space dock has repaired.
100	     */
101	    public static function lostUnits(int $fleetUnits): int
102	    {
103	        return $fleetUnits - self::repairedUnits($fleetUnits);
104	    }
105	
106	    /**
107	     * The same share as a ratio, for callers that scale a value instead of counting ships.
108	     */
109	    public static function repairFraction(): float
110	    {
111	        return self::repairPercent() / self::PERCENT_SCALE;
112	    }
113	
114	    /**
115	     * The share of a lost fleet the dock does not bring back, the factor a caller that prices a
116	     * battle charges a destroyed ship by.
117	     */
118	    public static function lostFraction(): float
119	    {
120	        return 1.0 - self::repairFraction();
121	    }
122	}

